/* wayland config.h — hand-written for our freestanding x86_64 environment.
 *
 * Generated by meson's autoconf-style probing upstream (root meson.build
 * config_h block: has_header/has_function for sys/prctl.h, accept4, mkostemp,
 * posix_fallocate, prctl, memfd_create, mremap, strndup, gettid, xucred).
 * Here we hardcode the values that match our kernel + musl libc state.
 *
 * Generated into the wayland source root (third_party/wayland/config.h) so
 * that the sources' own `#include "../config.h"` (connection.c, wayland-os.c
 * — from src/, resolves to third_party/wayland/config.h) and `#include
 * "config.h"` (wayland-shm.c, resolves via -I third_party/wayland) both hit
 * this file directly. Mirrors meson's in-tree configure_file placement.
 *
 * Copyright (c) 2026 hesse
 * SPDX-License-Identifier: MIT
 */

#ifndef WAYLAND_CONFIG_H
#define WAYLAND_CONFIG_H

#define PACKAGE "wayland"
#define PACKAGE_VERSION "1.25.91"

/* libc.so export-verified (nm -D --defined-only build/libc.so) */
#define HAVE_ACCEPT4 1
#define HAVE_POSIX_FALLOCATE 1
#define HAVE_MEMFD_CREATE 1
#define HAVE_MREMAP 1
#define HAVE_STRNDUP 1
#define HAVE_GETTID 1
#define HAVE_PRCTL 1

/* musl provides <sys/prctl.h>; FreeBSD-only headers absent */
#define HAVE_SYS_PRCTL_H 1
/* HAVE_SYS_PROCCTL_H / HAVE_SYS_UCRED_H — FreeBSD-only, undef */

/* mkostemp: libc.so has only mkstemp. wayland sources do NOT call mkostemp
 * (grep empty), so leaving it undefined is harmless (no fallback path). */

/* FreeBSD xucred / MSG_CMSG_CLOEXEC quirks — N/A on Linux */
#define HAVE_XUCRED_CR_PID 0
#define HAVE_BROKEN_MSG_CMSG_CLOEXEC 0

#endif /* WAYLAND_CONFIG_H */
